args=[sys.executable,str(BASE/'scripts/mgs-knowledge-control.py'),'checkpoint-upsert','--id','meta-manual-payments-digital-trust','--agent','zeus','--thread-id',c['thread_id'],'--objective','Refresh financeiro recorrente55IDs/H40 da ocorrência17/11 14:02Eastern;mesmojob/contrato,sem billing.','--state',state,'--next-step','Entregar resumo curto automaticamente; próximo tick do mesmo job '+r['next_run_at']+'. Nenhuma ação humana necessária para o refresh validado. Preservar lacunas históricas D e incidentes anteriores separados. REPORT-INFRA administrativo pendente pela restrição explícita de envio direto.','--source',r['evidence']]
